def find_solution(a, b, n):
    """
    Find integers x and y such that a*x + b*y = n.
    Returns:
      - (x, y) with x, y >= 0 if such solution exists
      - (x, y) with any integers if no non-negative solution exists but any integer solution exists
      - None if no integer solution exists
    """
    from math import gcd

    def extended_gcd(aa, bb):
        # Returns (g, x, y) such that a*x + b*y = g = gcd(a,b)
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        # No solution
        return None

    # Scale the solution to n
    x0 *= n // g
    y0 *= n // g

    # If a and b are zero, only n=0 solution is possible
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    # If a == 0, then b*y = n => y = n/b if divisible
    if a == 0:
        if n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
            else:
                # any integer solution is (0, y)
                return (0, y)
        else:
            return None

    # If b == 0, then a*x = n => x = n/a if divisible
    if b == 0:
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
            else:
                # any integer solution is (x, 0)
                return (x, 0)
        else:
            return None

    # General case: a and b != 0
    # Solutions are x = x0 + k*(b/g), y = y0 - k*(a/g)
    # We want to find k such that x >=0 and y >=0

    bg = b // g
    ag = a // g

    # x = x0 + k*bg >= 0 => k >= -x0/bg if bg > 0 else k <= -x0/bg
    # y = y0 - k*ag >= 0 => k <= y0/ag if ag > 0 else k >= y0/ag
    # Need to find integer k satisfying these inequalities

    import math

    k_min_x = math.ceil(-x0 / bg) if bg != 0 else None
    k_max_x = math.floor(-x0 / bg) if bg != 0 else None

    k_min_y = math.ceil(y0 / ag) if ag != 0 else None
    k_max_y = math.floor(y0 / ag) if ag != 0 else None

    # Determine valid k range
    k_low = -float('inf')
    k_high = float('inf')

    # For x >= 0
    if bg > 0:
        k_low = max(k_low, k_min_x)
    elif bg < 0:
        k_high = min(k_high, k_max_x)

    # For y >= 0
    if ag > 0:
        k_high = min(k_high, k_max_y)
    elif ag < 0:
        k_low = max(k_low, k_min_y)

    if k_low <= k_high:
        k = k_low  # take the smallest k satisfying constraints
        x = x0 + k * bg
        y = y0 - k * ag
        if x >= 0 and y >= 0:
            return (x, y)

    # If no non-negative solution, return any integer solution (x0, y0)
    return (x0, y0)

