def get_total_number_of_sequences(n, m):
    # dp[i][v]: number of sequences of length i ending with value v
    # v ranges from 1 to m
    dp = [0] * (m + 1)

    # For sequences of length 1, any value from 1 to m is valid
    for v in range(1, m + 1):
        dp[v] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # For each possible previous value
        for prev in range(1, m + 1):
            if dp[prev] == 0:
                continue
            # next element must be >= 2*prev and <= m
            start = 2 * prev
            if start > m:
                continue
            for nxt in range(start, m + 1):
                new_dp[nxt] += dp[prev]
        dp = new_dp

    return sum(dp)

