        arr (list of int): Sorted array of integers.
        start (int): Start index for the search.
        end (int): End index for the search.

    Returns:
        int: The smallest missing element.
    """
    if start > end:
        return end + 1

    mid = (start + end) // 2

    # The smallest missing element must be in the left half if the
    # value at mid is equal to mid (assuming array should contain all numbers from start)
    if arr[mid] == mid:
        return smallest_missing(arr, mid + 1, end)
    else:
        return smallest_missing(arr, start, mid - 1)

def permute_string(s):
    def backtrack(path, counter):
        if len(path) == len(s):
            print("".join(path))
            return
        for char in counter:
            if counter[char] > 0:
                path.append(char)
                counter[char] -= 1
                backtrack(path, counter)
                counter[char] += 1
                path.pop()

    from collections import Counter
    backtrack([], Counter(s))

def highest_Power_of_2(n: int) -> int:
    if n < 1:
        return 0
    power = 1
    while power <= n:
        power <<= 1
    return power >> 1

def find_remainder(arr, lens, n):
    result = 1
    for i in range(lens):
        result = (result * arr[i]) % n
    return result

def find_Max(arr, low, high):
    # Base case: if the array has only one element
    if low == high:
        return arr[low]

    # If the array is not rotated (sorted in ascending order)
    if arr[low] < arr[high]:
        return arr[high]

    mid = (low + high) // 2

    # Check if mid element is greater than its next element
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # Check if mid element is less than its previous element
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide whether to go to the left half or the right half
    if arr[mid] > arr[low]:
        return find_Max(arr, mid + 1, high)
    else:
        return find_Max(arr, low, mid - 1)

def recur_gcd(a, b):
    if b == 0:
        return a
    return recur_gcd(b, a % b)

