def text_match(text):
    return bool(re.fullmatch(r'ab*', text))

import re

def capital_words_spaces(s: str) -> str:
    return re.sub(r'(?<!^)(?=[A-Z])', ' ', s)

def odd_length_sum(arr):
    total = 0
    n = len(arr)
    for length in range(1, n+1, 2):
        for start in range(n - length + 1):
            total += sum(arr[start:start+length])
    return total

def is_triangleexists(a, b, c):
    # Check if all angles are positive and sum to 180 degrees
    return a > 0 and b > 0 and c > 0 and (a + b + c) == 180

def length_Of_Last_Word(s: str) -> int:
    s = s.rstrip()  # Remove trailing spaces
    last_space_index = s.rfind(' ')
    return len(s) - last_space_index - 1 if last_space_index != -1 else len(s)

def lcm(a: int, b: int) -> int:
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    return a * b // gcd(a, b)
